output_text:
[
  {
    "id": "no_cart_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where the customer is between shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "A customer must not push a cart into a single-file shelf aisle; the cart should be left outside before entry.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterSingleFileAisle"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "Whenever a customer parks a cart to enter a narrow aisle, they are obliged to retrieve the cart afterwards.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "cartParkingMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_only_at_aisle_mouths",
    "text": "Carts may only be parked at designated wide aisle mouths before a walk-in shelf aisle.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "open_shelf_interactions_require_cart",
    "text": "Shelf interactions from open, cart-accessible aisles require the customer to have their cart.",
    "abstraction": {
      "state_properties": {
        "openShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfServicePoint",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_service_only_main_shelf_faces",
    "text": "When holding a cart, customers should interact only with north/south main-aisle shelf faces, not east/west side-aisle shelf faces.",
    "abstraction": {
      "state_properties": {
        "sideShelfFace": {
          "or": [
            "shelfE",
            "shelfW"
          ]
        },
        "mainAisleShelfFace": {
          "or": [
            "shelfN",
            "shelfS"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "sideShelfFace"
        ]
      }
    }
  },
  {
    "id": "cart_required_in_open_areas",
    "text": "Except at the entrance, cart bay, or approved parking mouths, customers should not walk around open store aisles without a cart.",
    "abstraction": {
      "state_properties": {
        "openAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "cartlessOpenAreaException": {
          "or": [
            "at(0,7)",
            "at(1,7)",
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openAisle",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessOpenAreaException"
          }
        ]
      }
    }
  },
  {
    "id": "no_wandering_after_parking",
    "text": "After parking a cart at a narrow-aisle mouth, a customer must not leave that mouth into an open aisle without retrieving the cart.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "openAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "moveFromParkingMouthIntoOpenAisle": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "openAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "moveFromParkingMouthIntoOpenAisle"
    }
  }
]
